const NORMAL = hmUI.show_level.ONLY_NORMAL
const AOD = hmUI.show_level.ONLY_AOD

function img(x, y, src, show_level = NORMAL) {
  hmUI.createWidget(hmUI.widget.IMG, { x, y, src, show_level })
}

function time(digits, colonSrc, withSeconds, show_level, P) {
  const opts = {
    hour_zero: 1,
    hour_startX: P.hour[0],
    hour_startY: P.hour[1],
    hour_array: digits,
    hour_space: L.timeHSpace,
    hour_align: hmUI.align.LEFT,
    minute_zero: 1,
    minute_startX: P.minute[0],
    minute_startY: P.minute[1],
    minute_array: digits,
    minute_space: L.timeHSpace,
    minute_align: hmUI.align.LEFT,
    minute_follow: 0,
    show_level
  }
  if (withSeconds) {
    Object.assign(opts, {
      second_zero: 1,
      second_startX: L.second[0],
      second_startY: L.second[1],
      second_array: F.sec,
      second_space: L.secHSpace,
      second_align: hmUI.align.LEFT,
      second_follow: 0
    })
  }
  hmUI.createWidget(hmUI.widget.IMG_TIME, opts)
  if (colonSrc) img(P.colon[0], P.colon[1], colonSrc, show_level)
}

function date(digits, slashSrc, weekImgs, show_level, P) {
  hmUI.createWidget(hmUI.widget.IMG_DATE, {
    day_startX: P.day[0],
    day_startY: P.day[1],
    day_en_array: digits,
    day_sc_array: digits,
    day_tc_array: digits,
    day_zero: 1,
    day_space: L.dateHSpace,
    day_align: hmUI.align.LEFT,
    day_is_character: false,
    month_startX: P.month[0],
    month_startY: P.month[1],
    month_en_array: digits,
    month_sc_array: digits,
    month_tc_array: digits,
    month_zero: 1,
    month_space: L.dateHSpace,
    month_align: hmUI.align.LEFT,
    month_is_character: false,
    month_follow: 0,
    show_level
  })
  if (slashSrc) img(P.slash[0], P.slash[1], slashSrc, show_level)
  hmUI.createWidget(hmUI.widget.IMG_WEEK, {
    x: P.week[0],
    y: P.week[1],
    week_en: weekImgs,
    week_sc: weekImgs,
    week_tc: weekImgs,
    show_level
  })
}

function value(pos, font, type, extra = {}) {
  const [x, y, w] = pos
  const opts = {
    x,
    y,
    font_array: font,
    h_space: 3,
    align_h: hmUI.align.LEFT,
    padding: false,
    show_level: NORMAL
  }
  if (type !== undefined) opts.type = type
  if (w) Object.assign(opts, { w, align_h: hmUI.align.CENTER_H })
  return hmUI.createWidget(hmUI.widget.TEXT_IMG, Object.assign(opts, extra))
}

// Total sleep as decimal hours, "7.3" for 7h15. The built-in SLEEP type
// only gives h:mm, so this reads the sensor and sets the text itself.
function sleepHours(widget) {
  const sensor = hmSensor.createSensor(hmSensor.id.SLEEP)
  const update = () => {
    if (sensor.updateInfo) sensor.updateInfo()
    const minutes = sensor.getTotalTime() || 0
    widget.setProperty(hmUI.prop.TEXT, (Math.round(minutes / 6) / 10).toFixed(1))
  }
  update()
  hmUI.createWidget(hmUI.widget.WIDGET_DELEGATE, { resume_call: update })
}

function unit(src) {
  return { unit_en: src, unit_sc: src, unit_tc: src }
}

function status(pos, src, type) {
  hmUI.createWidget(hmUI.widget.IMG_STATUS, {
    x: pos[0],
    y: pos[1],
    src,
    type,
    show_level: NORMAL
  })
}

function click(rect, type) {
  const [x, y, w, h] = rect
  hmUI.createWidget(hmUI.widget.IMG_CLICK, { x, y, w, h, type, show_level: NORMAL })
}

WatchFace({
  build() {
    const T = hmUI.data_type
    // hmSetting.getLanguage() index: 3 es-ES, 15 pt-PT, 20 pt-BR; the rest get English
    const lang = { 3: 'es', 15: 'pt', 20: 'pt' }[hmSetting.getLanguage()] || 'en'

    // ---- normal screen
    // bg.png carries the static parts: icons, colon, slash,
    // and the dim "ghost" status icons.
    img(0, 0, F.bg)
    time(F.big, null, true, NORMAL, L)
    date(F.date, null, F.week[lang], NORMAL, L)

    status(L.bt, F.bt_off, hmUI.system_status.DISCONNECT)
    status(L.alarm, F.alarm, hmUI.system_status.CLOCK)
    status(L.dnd, F.dnd, hmUI.system_status.DISTURB)
    status(L.lock, F.lock, hmUI.system_status.LOCK)

    hmUI.createWidget(hmUI.widget.IMG_LEVEL, {
      x: L.battery[0],
      y: L.battery[1],
      image_array: F.battery,
      image_length: F.battery.length,
      type: T.BATTERY,
      show_level: NORMAL
    })
    value([L.batteryText[0], L.batteryText[1]], F.tiny, T.BATTERY, {
      w: L.batteryText[2],
      align_h: hmUI.align.RIGHT,
      h_space: 2,
      ...unit(F.tiny_pct)
    })

    value(L.heartText, F.mid, T.HEART, { invalid_image: F.mid_minus })
    value(L.spo2Text, F.mid, T.SPO2, { invalid_image: F.mid_minus, ...unit(F.mid_pct) })
    value(L.stressText, F.mid, T.STRESS, { invalid_image: F.mid_minus })

    hmUI.createWidget(hmUI.widget.IMG_LEVEL, {
      x: L.weatherIcon[0],
      y: L.weatherIcon[1],
      image_array: F.weather,
      image_length: F.weather.length,
      type: T.WEATHER_CURRENT,
      show_level: NORMAL
    })
    value(L.temp, F.mid, T.WEATHER_CURRENT, {
      negative_image: F.mid_minus,
      invalid_image: F.mid_minus,
      ...unit(F.mid_deg)
    })

    // bottom row; for STAND (current.target) dot_image is the separator,
    // so it gets a slash there
    const sm = { h_space: L.smHSpace }
    value(L.distText, F.sm, T.DISTANCE, { ...sm, dot_image: F.sm_dot })
    value(L.stepText, F.sm, T.STEP, sm)
    value(L.calText, F.sm, T.CAL, sm)
    sleepHours(value(L.sleepText, F.sm, undefined, {
      ...sm, text: '0.0', dot_image: F.sm_dot, ...unit(F.sm_h)
    }))
    value(L.standText, F.sm, T.STAND, { ...sm, dot_image: F.sm_slash })

    click(L.click.heart, T.HEART)
    click(L.click.spo2, T.SPO2)
    click(L.click.stress, T.STRESS)
    click(L.click.weather, T.WEATHER_CURRENT)
    click(L.click.steps, T.STEP)
    click(L.click.cal, T.CAL)
    click(L.click.sleep, T.SLEEP)
    click(L.click.stand, T.STAND)

    // ---- always-on display: dimmed time, date and weekday only
    time(F.big_aod, F.colon_aod, false, AOD, L.aod)
    date(F.date_aod, F.slash_aod, F.week_aod[lang], AOD, L.aod)
  }
})
